// ===== Isle of Emberfall — smeltable-alloy inventory icons (auto-generated) =====
// The 16 alloys (js/skills/alloys.js) have no dedicated reference sheet like
// the 32 base METALS did (ingots.png), so each is real art generated by
// blending its actual component ores' ingot colours onto one component's
// ingot SHAPE (same principle as the existing bronze recolor: hue-lock +
// saturation/value scale, generalized to a saturation-weighted hue blend for
// direction + an explicit real/lore-proportion weight for magnitude, with a
// couple of hand-tuned exceptions — white_gold and nickel_silver both looked
// like plain vivid gold/copper under the pure formula because their real
// alloys are famous for looking much whiter than a naive colour blend of
// their ingredients predicts, so those two got a manual saturation/hue
// nudge toward the pale/silver end). Source shapes are recroppped straight
// from assets/assorted sprites/ingots.png (border-flood-fill for alpha, no
// resampling), same pipeline as bar-icons-data.js and copper-bar-icon-data.js.
// Packed into a 4x4, 64px-tile sheet, key "al".
"use strict";
(function(){
  if (typeof ASSET_DATA === "undefined") window.ASSET_DATA = {};
  if (typeof SHEET_KEYS !== "undefined" && !SHEET_KEYS.includes("al")) SHEET_KEYS.push("al");
  if (typeof SHEET_TILE !== "undefined") SHEET_TILE["al"] = 64;
  ASSET_DATA["al"] = "data:image/png;base64,";
  var S = {"brass_bar": {"sx": 0, "sy": 0, "sw": 64, "sh": 64}, "pewter_bar": {"sx": 64, "sy": 0, "sw": 64, "sh": 64}, "cupronickel_bar": {"sx": 128, "sy": 0, "sw": 64, "sh": 64}, "tool_steel_bar": {"sx": 192, "sy": 0, "sw": 64, "sh": 64}, "rose_gold_bar": {"sx": 0, "sy": 64, "sw": 64, "sh": 64}, "sterling_silver_bar": {"sx": 64, "sy": 64, "sw": 64, "sh": 64}, "nickel_silver_bar": {"sx": 128, "sy": 64, "sw": 64, "sh": 64}, "white_gold_bar": {"sx": 192, "sy": 64, "sw": 64, "sh": 64}, "ferrotitanium_bar": {"sx": 0, "sy": 128, "sw": 64, "sh": 64}, "damasteel_bar": {"sx": 64, "sy": 128, "sw": 64, "sh": 64}, "voidforged_bar": {"sx": 128, "sy": 128, "sw": 64, "sh": 64}, "dragonsteel_bar": {"sx": 192, "sy": 128, "sw": 64, "sh": 64}, "twilight_bar": {"sx": 0, "sy": 192, "sw": 64, "sh": 64}, "skysteel_bar": {"sx": 64, "sy": 192, "sw": 64, "sh": 64}, "chronesteel_bar": {"sx": 128, "sy": 192, "sw": 64, "sh": 64}, "giltsilver_bar": {"sx": 192, "sy": 192, "sw": 64, "sh": 64}};
  for (var key in S) {
    var e = S[key];
    SPR["i_"+key+"_al"] = ["al", 0, 0, {sx:e.sx, sy:e.sy, sw:e.sw, sh:e.sh}];
    if (typeof ITEMS !== "undefined" && ITEMS[key]) ITEMS[key].icon = "i_"+key+"_al";
  }
})();
